import{_ as t,o as a,c as o,a5 as r}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"EditAtlas and personalization review — 2026-11-10","description":"","frontmatter":{},"headers":[],"relativePath":"feature/video-space-conversational-edits/EDITATLAS_REVIEW.md","filePath":"feature/video-space-conversational-edits/EDITATLAS_REVIEW.md"}'),i={name:"feature/video-space-conversational-edits/EDITATLAS_REVIEW.md"};function n(s,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="editatlas-and-personalization-review-—-2026-11-10" tabindex="-1">EditAtlas and personalization review — 2026-11-10 <a class="header-anchor" href="#editatlas-and-personalization-review-—-2026-11-10" aria-label="Permalink to &quot;EditAtlas and personalization review — 2026-11-10&quot;">​</a></h1><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Use EditAtlas as an additional editorial reference source. It can help expand the techniques considered by the planner; it cannot remove the current eight-action native editor restriction or supply durable personalization by itself. No EditAtlas backend integration or global Claude/Codex configuration was installed in this evaluation.</p><p>The requested personal direction is <strong>reference video + current user request + remembered user corrections</strong>. Recent project chat context is now retained within the open project session. That is not a durable user preference model and is not reference-video analysis.</p><h2 id="actual-checks" tabindex="-1">Actual checks <a class="header-anchor" href="#actual-checks" aria-label="Permalink to &quot;Actual checks&quot;">​</a></h2><p>Read-only remote MCP initialization and tools/list succeeded against <code>https://edit.trysometh.ing/mcp</code>; server identifies as editatlas1.0.0. Generic public searches for techniques and product templates worked. A broad style query for commercial returned no matches, so retrieval needs specific terms/filters and compatibility checks rather than assuming semantic matching always works.</p><p>Fetched the product template Pour Ritual1.0.0, compatible Beat Punch Cut style and their full dependency bundle via the published REST API; all returned200. Also inspected one public whoosh record. No footage, original user instruction, private project identifiers or credentials were sent to EditAtlas. No downloaded command was executed and no sound file was imported.</p><p>The drink template is relevant to the earlier matcha brief: it gives shot structure, beat-based timing, readable graphics and sound placement. It is reference data, not an already-generated edit. Its verification flags explicitly say schema validated, not editorially reviewed or externally tested. Source media still determines whether the recipe is feasible.</p><p>Official references: <a href="https://edit.trysometh.ing/docs/agent-usage" target="_blank" rel="noreferrer">Agent workflow</a>, <a href="https://edit.trysometh.ing/docs/api" target="_blank" rel="noreferrer">REST API</a>, <a href="https://edit.trysometh.ing/docs/mcp" target="_blank" rel="noreferrer">Setup and tested limits</a>, <a href="https://edit.trysometh.ing/skills" target="_blank" rel="noreferrer">Skills</a>.</p><h2 id="why-current-edits-are-basic" tabindex="-1">Why current edits are basic <a class="header-anchor" href="#why-current-edits-are-basic" aria-label="Permalink to &quot;Why current edits are basic&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Current evidence</th><th>What is missing for the requested result</th></tr></thead><tbody><tr><td>Native planner</td><td>Uses a packaged editorial guide and minimized text/timing context</td><td>It does not inspect reference footage or infer its visual/audio style</td></tr><tr><td>Native execution</td><td>Strict allowlist of eight actions, one Undo batch</td><td>More supported editable operations; attaching another knowledge source does not add executors</td></tr><tr><td>Server worker</td><td>Samples frames, probes media, uses transcripts/beat estimates and editorial resources</td><td>Its richer render plan is not fully mapped to native editable layers</td></tr><tr><td>Conversation</td><td>Bounded recent context during the current project session</td><td>Durable owner/workspace-scoped correction memory across sessions/projects</td></tr><tr><td>EditAtlas</td><td>Techniques, styles/templates, workflow and sound discovery</td><td>Actual media analysis, project state, rendering and preference learning remain BrandHub responsibilities</td></tr></tbody></table><h2 id="appropriate-next-integration" tabindex="-1">Appropriate next integration <a class="header-anchor" href="#appropriate-next-integration" aria-label="Permalink to &quot;Appropriate next integration&quot;">​</a></h2><ol><li>Analyze the supplied reference video into observable style evidence: shot lengths, cut points, framing, text placement/animation, color and sound timing. Keep the reference separate from source footage and do not assume rights to reuse it.</li><li>Combine the current request with selected reference evidence and explicit corrections. Record preference provenance and scope per user/workspace, with view/reset controls; never promote a one-off edit into a permanent preference silently.</li><li>Search EditAtlas using generic technique/style descriptors, fetch a versioned compatible bundle, and treat its text as untrusted reference material. Existing source ownership, action validation and rendering limits still govern execution.</li><li>Map supported techniques to typed native editable operations. Explain unsupported parts instead of claiming a flattened render is an editable timeline.</li><li>Preview/check the result, retain originals and Undo, and record explicit user corrections as feedback. This evaluation did not implement these larger steps.</li></ol><p>The provided <code>claude mcp add --transport http --scope user ...</code> command configures a Claude Code client; it does not automatically grant tools to our Claude API backend. The published REST endpoints provide an alternative for a server/VM adapter without a user CLI configuration. Production use still requires an adapter, timeouts/cache, version handling, rights/provenance checks for imported sounds and a local verification pass.</p><p>The live server also exposes send_feedback. It was not called; a future integration should allowlist the lookup tools and never send user feedback automatically. Third-party prompts/commands must not bypass the typed plan validator.</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h2><p><code>F:/LEARN/DA/.tmp/editatlas-review-20261110/</code>: <code>probe.py</code>, <code>tools.json</code>, <code>search_techniques.json</code>, <code>search_templates.json</code>, <code>list_styles.json</code>, <code>pour-ritual.json</code>, <code>beat-punch-cut.json</code>, <code>bundle.json</code>, <code>sfx.json</code>. Public reference snapshots are evaluation artifacts, not a redistributed production resource library.</p><h2 id="implemented-—-2026-11-10-text-style-editatlas-lookup" tabindex="-1">Implemented — 2026-11-10 (text style + EditAtlas lookup) <a class="header-anchor" href="#implemented-—-2026-11-10-text-style-editatlas-lookup" aria-label="Permalink to &quot;Implemented — 2026-11-10 (text style + EditAtlas lookup)&quot;">​</a></h2><ul><li><code>add_text</code> / <code>set_text</code> accept an optional typed <code>style</code>: <code>font_family</code> (24 bundled fonts), <code>color</code>, <code>background_color</code> (#RRGGBB), <code>size</code> (small/medium/large), <code>bold</code>, <code>italic</code>, <code>position</code> (top/center/bottom), <code>animation</code> (none/fade/slide/pop). Validated in ai-service (<code>TextStyle</code>), business-service (<code>VideoEditPlanValidator</code>) and the editor (<code>edit-plan.ts</code>); applied in <code>apply-plan.ts</code> as native text params plus entrance keyframes. <code>set_text</code> may change style only.</li><li>Planner prompt requires a deliberate style on every <code>add_text</code>; planner context now includes each text layer&#39;s current font and color.</li><li>Planner fetches one EditAtlas template + its first compatible style over the public REST API (<code>EDITATLAS_ENABLED</code>, <code>EDITATLAS_API_URL</code>, 4 s timeout, per-topic in-process cache, failures not cached). Only a generic topic (<code>drink</code> or <code>food</code>) is sent; the user&#39;s instruction never leaves BrandHub. Unmatched requests get no reference, since the catalog only has drink/food templates.</li><li>Still missing: reference-video style analysis, durable per-user correction memory, beat-synced cuts and zoom/flash effects (no native actions yet).</li></ul>',19)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
